style.css:
@-moz-document domain("example.com") {
/* Fondo negro */
  body {
    background-color: #000 !important;
    overflow: hidden !important; /* Evita el scroll */
  }

  /* Crear el contenedor para los círculos */
  body::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    z-index: -1;
    background-color: #000;
  }

  /* Círculos animados */
  .circle {
    position: fixed;
    background-color: white;
    border-radius: 50%;
    opacity: 0.8;
    animation: fall linear infinite;
  }

  /* Animación de caída */
  @keyframes fall {
    0% {
      transform: translateY(-100%);
      opacity: 1;
    }
    100% {
      transform: translateY(110%);
      opacity: 0;
    }
  }
}
